from fastapi import APIRouter, HTTPException, status
from typing import List

from models import Book, BookCreate, BookUpdate
from database import get_connection

router = APIRouter(prefix="/books", tags=["books"])


@router.get("/", response_model=List[Book])
def get_books():
    conn = get_connection()
    rows = conn.execute("SELECT id, title, author, status FROM books ORDER BY id").fetchall()
    conn.close()
    return [dict(row) for row in rows]


@router.post("/", response_model=Book, status_code=status.HTTP_201_CREATED)
def create_book(book_in: BookCreate):
    conn = get_connection()
    cursor = conn.execute(
        "INSERT INTO books (title, author, status) VALUES (?, ?, ?)",
        (book_in.title, book_in.author, book_in.status),
    )
    conn.commit()
    row = conn.execute(
        "SELECT id, title, author, status FROM books WHERE id = ?", (cursor.lastrowid,)
    ).fetchone()
    conn.close()
    return dict(row)


